for(const row of archive.sources)assert.equal(sha(row.bytes),row.sha256);
function naturalWorld(index:number){
  const account=makeAccount(),manifest=buildManifest(account,991),w:any=new World(account,Object.freeze(manifest));
  w.createPlayer(CLASSES.find(c=>c.id==='warrior')!,{startingCompanions:false});w.sim.bindGeographyPolicies();
  const source=createNativeGeographyReader(captureNativeGeographySource(991));
  const spec=makeMassNativeGeographySpec(source.identity,{schema:1,algorithm:'bigint-relative-native-map-v1',addressSpan:960,physicalOrigin:address('surface','0','0',0,0,960),nativeOrigin:{x:0,y:0},physicalUnitsPerNativeUnit:{numerator:'20',denominator:'1'},nativeDimension:'surface',nativeBounds:{minX:-10000,minY:-10000,maxX:10000,maxY:10000},outsideDomain:'refuse',rounding:'nearest-binary64-ties-even-once'});
  const mapping=new MassNativeGeography(spec),target=index===0?{x:-55,y:160}:{x:-35,y:1280},request=mapping.ownerContext('native-source-course/'+index,mapping.physicalAnchor(target));
  const z=placeZoneAt(request.requestedTarget,null,w.zoneMap,request.requestedSeed,{seed:request.requestedSeed,fieldBiome:true,biomeFor:source.biomeAt,biomeDepthFor:source.biomeDepth,climateFor:source.climateAt,levelFor:w.levelFor,courseFor:w.courseMintFor('surface')});
  w.zoneMap[z.id]=z;return {w,z,manifest,request};
}
installHeadlessShims();registerAllPackageFactions();validateContent();
const originalWarning=console.warn;const warnings:string[]=[];console.warn=(...args:unknown[])=>warnings.push(args.join(' '));
function traced<T>(key:string,fn:()=>T):T {const next=Rng.prototype.next,draws:number[][]=[];Rng.prototype.next=function(){const before=this.snapshot(),value=next.call(this);draws.push([before,value,this.snapshot()]);return value;};try{return fn();}finally{Rng.prototype.next=next;assert.equal(sha(JSON.stringify(draws)),archive.tapes[key],key+' complete native draw tape');}}
let naturalPairs=0,ownerPairs=0,absentReceipts=0,relocatedAnchors=0,physicalMoves=0,physicalLegs=0;
try {
 // Re-enter the exact retained native generation boundary: full definition, extra
 // fixtures, actual entry/exits and geometry cursor, never a substituted recipe.
 for(const fixture of archive.nativeFixtures){
  const input=structuredClone(restoreNativeAreaData<any>(fixture.input));
  const expected=structuredClone(restoreNativeAreaData<any>(fixture.expected));
  const random=Rng.fromState(input.geometryCursor),prior=Math.random;let ambientDraws=0;
  Math.random=()=>{ambientDraws++;throw Error('unexpected ambient generation draw');};
  let result;try{result=traced('natural/'+fixture.label,()=>generateLayout(input.def,input.arena,random,input.entry,input.exits.map((x:any)=>x.pos),input.extraFixtures));}finally{Math.random=prior;}
  const {walk,...layout}=result;
  const actual={label:fixture.label,def:input.def,arena:input.arena,entry:input.entry,exits:input.exits,layout,walk:walk instanceof GridWalkField?{kind:'grid',packed:walk.pack()}:{kind:'analytic',type:walk?.constructor?.name??null},geometryCursor:random.snapshot()};
  assert.equal(serializeNativeAreaData(actual),fixture.expected,fixture.label+' complete native output and geometry cursor');
  assert.equal(ambientDraws,0);assert.equal(random.snapshot(),expected.geometryCursor);naturalPairs++;
 }
 // Fresh native source minting and real campaign ignition: 20 complete preparation
 // courses, including explicit remembered seed1031 and native seed0 behavior.
 for(let index=0;index<2;index++)withSeededRandom(991,()=>{
  const {w,z,request}=naturalWorld(index);w.loadZone(z.id);
  const actual={sim:w.sim,arena:w.arena,exits:w.exits,player:w.player,actors:w.actors};
  const field=actual.sim.crusadeField;field?.update(0,w.simView());
  for(const held of [false,true]){if(held){assert(field?.devIgnite(w.simView(),z.id,180));assert(field.crusadeOn(z.id)?.cityFill);}
   for(const mode of ['fresh','remembered','boundless','seedless','zero-seed']){
    const label=index+'/'+held+'/'+mode,expected=archive.goldens.find((x:any)=>x.label===label);assert(expected);
    const def={...z,...(mode==='boundless'?{boundless:true}:{}),...(mode==='seedless'?{seed:undefined}:mode==='zero-seed'?{seed:0}:{})};
    const entry={...w.zoneEntry},memory={seed:1031,charBorn:21,savedAt:99,enemies:[]};
    const scene={zone:def,actors:actual.actors,player:actual.player},geometry={state:scene,arena:actual.arena,exits:actual.exits,currentZoneSeed:789,farPointDraws:57},state={inCave:false,charBorn:65,charRegrowAcc:13,crusadeWorksAt:{x:6,y:8}},campaign={zoneMemory:new Map(mode==='remembered'||mode==='boundless'?[[def.id,memory]]:[]),time:101,sim:actual.sim};
    const owner=new NativeAreaSceneGeneration({scene,geometry,state,campaign});
    const ambient=new Rng(62415),prior=Math.random;let draws=0;Math.random=()=>{draws++;return ambient.next();};
    let out;try{out=traced('owner/'+label,()=>owner.generate(entry));}finally{Math.random=prior;}
    const {walk,...layout}=out.layout;assert(!walk||walk instanceof GridWalkField);const packed=walk?.pack();
    assert.equal(sha(JSON.stringify({layout,packed})),expected.layoutHash,label+' whole layout');
    assert.deepEqual({canonicalSeed:request.requestedSeed,seed:out.layoutSeed,rng:out.rng.snapshot(),ambient:ambient.snapshot(),draws,worksAt:state.crusadeWorksAt},{canonicalSeed:expected.canonicalSeed,seed:expected.seed,rng:expected.rng,ambient:expected.ambient,draws:expected.draws,worksAt:expected.worksAt},label+' native source and dual-stream continuation');
    assert.deepEqual(layout.structures===undefined?undefined:JSON.parse(JSON.stringify(layout.structures)),expected.structures,label+' all resolved structures');
    assert.deepEqual(Object.fromEntries(Object.entries(layout).filter(([,v])=>Array.isArray(v)).map(([k,v])=>[k,(v as any[]).length])),expected.collections);
    const receipts=(layout as any).fixturePlacements;
    if(!expected.fixtures){assert.equal(Object.hasOwn(layout,'fixturePlacements'),false,label+' absent receipt field preserved');absentReceipts++;}
    else assert.deepEqual(JSON.parse(JSON.stringify(receipts)),expected.fixtures);
    for(const receipt of receipts??[]){const st=layout.structures?.find(s=>s.id===receipt.structureId);assert(st);assert.deepEqual(receipt.rect,st.rect);assert.deepEqual(receipt.center,{x:st.rect.x+st.rect.w/2,y:st.rect.y+st.rect.h/2});}
    const main=receipts?.find((f:any)=>f.fixtureIndex===(def.fixtures?.length??0));if(held&&main?.reseated){assert.deepEqual(state.crusadeWorksAt,main.center,label+' runtime works anchor transport');relocatedAnchors++;}
    ownerPairs++;
   }
  }
 });
 assert.equal(ownerPairs,20);assert(absentReceipts>0);assert.equal(relocatedAnchors,3);
 // Two references to the same fixture object are two authored occurrences.
 const duplicate=JSON.parse(archive.duplicateInput),fixture={structure:'watchtower',x:500,y:500},def={...duplicate.def,fixtures:[fixture]};
 const duplicated:any=withSeededRandom(713,()=>generateLayout(def,duplicate.arena,new Rng(duplicate.seed),duplicate.entry,duplicate.exits.map((e:any)=>e.pos),[fixture]));
 assert.equal(def.fixtures[0],fixture);assert.deepEqual(duplicated.fixturePlacements.map((f:any)=>f.fixtureIndex),[0,1]);assert.equal(new Set(duplicated.fixturePlacements.map((f:any)=>f.structureId)).size,2);
 for(const f of duplicated.fixturePlacements){const s=duplicated.structures.find((s:any)=>s.id===f.structureId);assert(s);assert.deepEqual(f.rect,s.rect);assert.deepEqual(f.center,{x:s.rect.x+s.rect.w/2,y:s.rect.y+s.rect.h/2});}
 // Genuine native geometry adoption and ordinary movement, at fixed1/60. These
 // retained routes enter actual doors/interiors, including valid carve-first sites.
 // The only scene mutation before movement is opening genuine native doors.
 for(const course of archive.physical)withSeededRandom(course.seed,()=>{
  const v=course.wire?structuredClone(restoreNativeAreaData<any>(course.snapshot)):JSON.parse(course.snapshot);
  const account=makeAccount(),w:any=new World(account,Object.freeze(buildManifest(account,course.seed)));w.createPlayer(CLASSES.find(c=>c.id==='warrior')!,{startingCompanions:false});
  w.zoneMap[v.def.id]=structuredClone(v.def);w.zone=structuredClone(v.def);w.arena={...v.arena,boundless:!!v.def.boundless};w.exits=structuredClone(v.exits);w.currentZoneSeed=v.seed??v.def.seed;
  const layout={...structuredClone(v.layout),walk:GridWalkField.unpack(course.wire?v.walk.packed:v.packed)};
  w.runNativeAreaLayout(w.zone,layout,v.entry,w.zone.id);assert.equal(w.walk,layout.walk);assert.equal(w.doodads,layout.doodads);
  const retained=w.doodads.slice(),doors=w.doodads.filter((d:any)=>d.door);for(const d of doors)w.setDoorState(d.door.id,'open',{silent:true});
  const actor=w.player;assert.equal(actor.radius,15);assert(!w.devNoclip&&!actor.flying&&!w.levitating(actor));
  const route=course.route;assert(route.length>2);assert.deepEqual(route[0],v.entry,course.label+' route starts at genuine entry');
  function sweep(a:any,b:any){actor.pos={...a};const n=Math.max(1,Math.ceil(Math.hypot(b.x-a.x,b.y-a.y)/5));for(let j=1;j<=n;j++){const q={x:a.x+(b.x-a.x)*j/n,y:a.y+(b.y-a.y)*j/n};const moved=w.clampPos(q,15,actor.pos,{mover:actor});assert(Math.hypot(moved.x-q.x,moved.y-q.y)<1e-7,course.label+' native body sweep');actor.pos=moved;}physicalLegs++;}
  for(let i=1;i<route.length;i++){sweep(route[i-1],route[i]);sweep(route[i],route[i-1]);}
  function walk(points:any[]){actor.pos={...points[0]};for(let i=1;i<points.length;i++){const goal=points[i];let count=0;while(Math.hypot(goal.x-actor.pos.x,goal.y-actor.pos.y)>4){const dx=goal.x-actor.pos.x,dy=goal.y-actor.pos.y,d=Math.hypot(dx,dy);w.moveActor(actor,dx/d,dy/d,1/60);physicalMoves++;assert(++count<1000,course.label+' ordinary movement stalled');}}}
  walk(route);walk([...route].reverse());assert.deepEqual(w.doodads,retained,course.label+' no omitted scenery');
 });
}finally{console.warn=originalWarning;}
// Load private actual helpers only for bounded mechanism controls. This is a
